'use strict';
(()=>{
const topics=window.TOPICS,labels={new:'Не начинал',learning:'Изучаю',practice:'Решаю сам',known:'Уже знаю',reviewed:'Повторил успешно',struggling:'Не получается'},weights={new:1,learning:.8,practice:.5,known:.25,reviewed:.1,struggling:1.4};
function record(state,id){return state.strategy?.topics?.[id]||{status:'new'}}
function known(state,id){return ['known','reviewed'].includes(record(state,id).status)}
function selected(cp,k){let list=topics.filter(t=>t.subject===k);if(cp.id==='week1'||cp.id==='week2'){const ids={math:['1.1','1.2','1.3','1.4'],ru:['3.1.1','3.2.1','3.4.1','3.1.2'],physics:['prep','1.1.1','1.1.2','1.1.3']}[k].slice(0,cp.id==='week1'?2:4);return ids.map(code=>list.find(t=>t.code===code)).filter(Boolean)}if(cp.id==='2027-04'||cp.id==='2027-05')return list;return list.filter(t=>t.period===cp.id)}
function summary(state,cp,k){let list=selected(cp,k);return {total:list.length,known:list.filter(t=>known(state,t.id)).length,reviewed:list.filter(t=>record(state,t.id).status==='reviewed').length}}
function rebalance(source,now){const state=JSON.parse(JSON.stringify(source)),bySubject=Object.keys(names),factor={};for(let k of bySubject){let list=topics.filter(t=>t.subject===k);factor[k]=list.reduce((n,t)=>n+weights[record(state,t.id).status],0)/list.length}
 const tasks=state.tasks.filter(t=>!t.teacher&&!t.done&&!t.actual&&t.date>=now);let weeks=new Map();for(let t of tasks){const w=monday(t.date);if(!weeks.has(w))weeks.set(w,[]);weeks.get(w).push(t)}let changes=0;const queues={};for(let k of bySubject)queues[k]=topics.filter(t=>t.subject===k).sort((a,b)=>{let ar=record(state,a.id).status,br=record(state,b.id).status;return (ar==='struggling'?-1:0)-(br==='struggling'?-1:0)||Number(known(state,a.id))-Number(known(state,b.id))||a.period.localeCompare(b.period)||a.code.localeCompare(b.code,undefined,{numeric:true})});let next={ru:0,math:0,physics:0};
 for(let [,items]of [...weeks].sort(([a],[b])=>a.localeCompare(b))){let base={ru:0,math:0,physics:0},used={ru:0,math:0,physics:0};for(let t of items){const k=t.originalSubject||t.subject;base[k]+=t.minutes}const scaled=bySubject.map(k=>[k,base[k]*factor[k]]).filter(([,v])=>v>0);for(let t of items.sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id))){t.originalSubject=t.originalSubject||t.subject;let k=t.recoveryFor?t.subject:scaled.reduce((best,row)=>used[row[0]]/row[1]<used[best[0]]/best[1]?row:best,scaled[0])[0];if(t.subject!==k)changes++;t.subject=k;used[k]+=t.minutes;const pool=queues[k],topic=pool[next[k]++%pool.length];t.suggestedTopic=topic.id}}
 return {state,changes};}
let filterSubject='all',search='',filterStatus='all';
function render(){const current=state.strategy?.topics||{},all=topics.length,n=topics.filter(t=>known(state,t.id)).length,r=topics.filter(t=>record(state,t.id).status==='reviewed').length;$('#topicProgress').innerHTML=`<div><strong>${(n/all*100).toLocaleString('ru-RU',{maximumFractionDigits:1})}%</strong><span> тем отмечено знакомыми · ${n} из ${all}</span></div><p class="muted">Из них повторено: ${r}. «Уже знаю» — самооценка, а не результат независимого теста. По умолчанию все темы начинаются с нуля.</p>`;
const visible=topics.filter(t=>(filterSubject==='all'||t.subject===filterSubject)&&(filterStatus==='all'||record(state,t.id).status===filterStatus)&&(!search||(t.code+' '+t.title).toLowerCase().includes(search)));
$('#topicList').innerHTML=Object.keys(names).map(k=>{let list=visible.filter(t=>t.subject===k);if(!list.length)return '';return `<details ${filterSubject!=='all'||search?'open':''}><summary>${names[k]}<span class="muted">${list.filter(t=>known(state,t.id)).length} / ${list.length} знакомы</span></summary><div class="topicrows">${list.map(t=>{const v=record(state,t.id),cp=window.ROADMAP.checkpoints.find(c=>c.id===t.period),eff=window.planEngine.effective(cp,state);return `<div class="topicrow"><div><span class="badge ${k}">${t.source==='codifier'?'ФИПИ '+t.code:'Дополнение к подготовке'}</span><strong>${escape(t.title)}</strong><small>Освоить и повторить до ${fmt(eff.end)} · ${labels[v.status]}</small><a href="materials/${k}-${t.source==='codifier'?'codifier':'specification'}-2027.pdf" target="_blank" rel="noopener">Полное содержание в документе</a></div><label><span class="sr-label">Знание темы ${escape(t.title)}</span><select aria-label="Знание темы ${escape(t.title)}" data-topic="${t.id}" data-roadmap-write>${Object.entries(labels).map(([value,label])=>`<option value="${value}" ${v.status===value?'selected':''}>${label}</option>`).join('')}</select></label></div>`}).join('')}</div></details>`}).join('')||'<p class="muted">По этому фильтру тем нет.</p>';window.markCloud?.controls()}
$('#topicSubject').onchange=e=>{filterSubject=e.target.value;render()};$('#topicSearch').oninput=e=>{search=e.target.value.trim().toLowerCase();render()};$('#topicStatus').onchange=e=>{filterStatus=e.target.value;render()};
document.addEventListener('change',e=>{const id=e.target.dataset.topic;if(!id||window.markCloud?.active&&!window.markCloud.writable)return;const t=topics.find(x=>x.id===id),status=e.target.value,old=record(state,id);if(!t||!Object.hasOwn(labels,status))return;if(status==='reviewed'&&(!old.at||!['known','practice','reviewed'].includes(old.status)||shift(old.at,7)>today)){toast('Сначала отметь «Решаю сам» или «Уже знаю». Повторная проверка — не раньше чем через 7 дней.');render();return}state.strategy={...state.strategy,topics:{...state.strategy?.topics,[id]:{status,at:today}}};if(status==='struggling'){window.replanFromTopic(t.period);return}if(state.strategy.planning?.feedback?.[t.period]?.status==='struggling'&&!topics.some(x=>x.period===t.period&&record(state,x.id).status==='struggling')){state.strategy.planning.feedback[t.period]={status:'ontrack',at:today};if(state.strategy.planning.lastFailed===t.period)state.strategy.planning.issues=null}const out=rebalance(state,today);state=out.state;save();window.renderRoadmap?.();render();window.renderStudyWeek?.();toast(status==='known'?`Тема знакома. Прогресс и приоритеты пересчитаны; перераспределено занятий: ${out.changes}.`:'Статус темы и приоритеты обновлены')});
window.topicEngine={record,known,selected,summary,rebalance,render};render();window.renderRoadmap?.();
})();
